pub fn validate_commit_bundle(value: &serde_json::Value) -> Result<(), String> {
    validate_schema(COMMIT_BUNDLE, value)?;
    let mut ids = std::collections::HashSet::new();
    for artifact in value
        .get("artifacts")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
    {
        let id = artifact
            .get("artifactId")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| "artifactId missing".to_string())?;
        if !ids.insert(id) {
            return Err("duplicate artifactId".to_string());
        }
    }
    Ok(())
}

